import { useEffect, useRef, useState } from "react";

const TASKS_VISION_CDN = "https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.35";
const FACE_LANDMARKER_MODEL =
  "https://storage.googleapis.com/mediapipe-models/face_landmarker/face_landmarker/float16/latest/face_landmarker.task";
const FACE_DETECTOR_MODEL =
  "https://storage.googleapis.com/mediapipe-models/face_detector/blaze_face_short_range/float16/1/blaze_face_short_range.tflite";

export default function useFaceMesh({ videoRef, enabled, onResults }) {
  const faceLandmarkerRef = useRef(null);
  const faceDetectorRef = useRef(null);
  const frameRef = useRef(null);
   const [isDetectorReady, setIsDetectorReady] = useState(false);
   const [landmarkCount, setLandmarkCount] = useState(0);
   const [trackingStatus, setTrackingStatus] = useState("Idle");
   const [detectorError, setDetectorError] = useState(null);

  useEffect(() => {
    let cancelled = false;

    const loadFaceLandmarker = async () => {
      setTrackingStatus("Loading detector");

      try {
        const { FaceDetector, FaceLandmarker, FilesetResolver } = await import(
          /* @vite-ignore */ TASKS_VISION_CDN
        );
        const vision = await FilesetResolver.forVisionTasks(`${TASKS_VISION_CDN}/wasm`);
        
        let faceLandmarker;
        try {
          faceLandmarker = await FaceLandmarker.createFromOptions(vision, {
            baseOptions: {
              modelAssetPath: FACE_LANDMARKER_MODEL,
              delegate: "GPU"
            },
            numFaces: 1,
            outputFaceBlendshapes: false,
            outputFacialTransformationMatrixes: false,
            runningMode: "VIDEO",
            minFaceDetectionConfidence: 0.6,
            minFacePresenceConfidence: 0.6,
            minTrackingConfidence: 0.6
          });
        } catch (gpuError) {
          console.error("GPU delegate failed, falling back to CPU:", gpuError);
          faceLandmarker?.close();
          faceLandmarker = await FaceLandmarker.createFromOptions(vision, {
            baseOptions: {
              modelAssetPath: FACE_LANDMARKER_MODEL,
              delegate: "CPU"
            },
            numFaces: 1,
            outputFaceBlendshapes: false,
            outputFacialTransformationMatrixes: false,
            runningMode: "VIDEO",
            minFaceDetectionConfidence: 0.6,
            minFacePresenceConfidence: 0.6,
            minTrackingConfidence: 0.6
          });
        }

        let faceDetector = null;
        try {
          faceDetector = await FaceDetector.createFromOptions(vision, {
            baseOptions: {
              modelAssetPath: FACE_DETECTOR_MODEL,
              delegate: "GPU"
            },
            runningMode: "VIDEO",
            minDetectionConfidence: 0.6
          });
        } catch (gpuError) {
          console.warn("FaceDetector GPU delegate failed, falling back to CPU:", gpuError);
          faceDetector?.close();

          try {
            faceDetector = await FaceDetector.createFromOptions(vision, {
              baseOptions: {
                modelAssetPath: FACE_DETECTOR_MODEL,
                delegate: "CPU"
              },
              runningMode: "VIDEO",
              minDetectionConfidence: 0.6
            });
          } catch (cpuError) {
            console.warn("FaceDetector unavailable; using FaceMesh earlobe estimate:", cpuError);
          }
        }

        if (cancelled) {
          faceLandmarker.close();
          faceDetector?.close();
          return;
        }

        faceLandmarkerRef.current = faceLandmarker;
        faceDetectorRef.current = faceDetector;
        setIsDetectorReady(true);
        setTrackingStatus("Searching");
      } catch (error) {
        console.error("FaceLandmarker failed to load:", error);
        setTrackingStatus("Detector failed");
        setDetectorError(error);
      }
    };

    loadFaceLandmarker();

    return () => {
      cancelled = true;
      cancelAnimationFrame(frameRef.current);
      faceLandmarkerRef.current?.close();
      faceDetectorRef.current?.close();
      faceLandmarkerRef.current = null;
      faceDetectorRef.current = null;
      setIsDetectorReady(false);
    };
  }, []);

  useEffect(() => {
    if (
      !enabled ||
      !isDetectorReady ||
      !videoRef.current ||
      !faceLandmarkerRef.current
    ) {
      return undefined;
    }

    let cancelled = false;

    const processFrame = async () => {
      if (
        cancelled ||
        !videoRef.current ||
        !faceLandmarkerRef.current
      ) {
        return;
      }

      if (videoRef.current.readyState >= 2) {
        const timestamp = performance.now();
        const landmarkResults = await faceLandmarkerRef.current.detectForVideo(
          videoRef.current,
          timestamp
        );
        const detectorResults = faceDetectorRef.current
          ? await faceDetectorRef.current.detectForVideo(videoRef.current, timestamp)
          : null;
        const face = landmarkResults?.faceLandmarks?.[0];

        setLandmarkCount(face ? face.length : 0);
        setTrackingStatus(face ? "Tracking" : "Searching");
        onResults?.({
          faceDetections: detectorResults?.detections,
          multiFaceLandmarks: landmarkResults?.faceLandmarks
        });
      }

      frameRef.current = requestAnimationFrame(processFrame);
    };

    processFrame();

    return () => {
      cancelled = true;
      cancelAnimationFrame(frameRef.current);
    };
  }, [enabled, isDetectorReady, onResults, videoRef]);

  return {
    landmarkCount,
    trackingStatus,
    detectorError
  };
}
